  'help.ctx.dashboard.title': 'לוח הבקרה',
  'help.ctx.dashboard.summary':
    'לוח הבקרה מציג את כל הטיולים שלכם. הכרטיס בראש העמוד, שמעוצב ככרטיס עלייה למטוס, מציג את הטיול שמתקיים עכשיו או את הטיול הבא. השורה שמתחתיו מסכמת את הטיולים שלכם עד כה, והכרטיסים מציגים את כל הטיולים שאתם מתכננים, שהעברתם לארכיון או שכבר סיימתם.',
  'help.ctx.dashboard.bullet.1':
    'כרטיס עלייה למטוס: הטיול שמתקיים עכשיו או הטיול הבא, עם התאריכים, המטיילים, המקומות והספירה לאחור. לחצו עליו כדי לפתוח את הטיול. ארבעת הכפתורים בפינה הימנית העליונה מאפשרים לערוך, לשכפל, להעביר לארכיון או למחוק אותו.',
  'help.ctx.dashboard.bullet.2':
    'נתוני הטיולים: המדינות שביקרתם בהן, מספר הטיולים, ימי הטיול ומרחק הטיסות, בכל הטיולים שלכם.',
  'help.ctx.dashboard.bullet.3':
    'כרטיסי טיולים בתצוגת רשת או רשימה, עם סינון לפי מתוכנן, בארכיון והסתיים. תיבת החיפוש שמעליהם מחפשת בכל הטיולים שלכם בבת אחת, לפי כותרת, תאריך או מקום בטיול. הכפתורים לעריכה, שכפול, העברה לארכיון ומחיקת טיול נמצאים בפינה הימנית העליונה של התמונה בכל כרטיס.',
  'help.ctx.dashboard.bullet.4':
    'ווידג׳טים בצד ימין: ממיר מטבעות, אוספים (כשהתוסף אוספים פעיל), שעוני עולם, הזמנות קרובות וווידג׳טים מתוספים. אפשר לכבות את הווידג׳טים המובנים תחת הגדרות, מראה.',
  'help.ctx.dashboard.bullet.5': 'גם הכרטיס טיול חדש וגם הכפתור בפינה הימנית התחתונה מאפשרים ליצור טיול חדש.',
  'help.guide.create-trip.title': 'יצירת טיול',
