    'לחצו על טיול חדש. הכרטיס שבסוף רשימת הטיולים והכפתור בפינה הימנית התחתונה מבצעים את אותה הפעולה.',
  'help.guide.create-trip.step.2': 'תנו לטיול שם. זהו שדה החובה היחיד; את כל השאר אפשר להוסיף בהמשך.',
